insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('5552f280-f553-52d8-af83-acfa1effb6f7', 'drill-rw-information-ideas', 'Reading: Information and Ideas', 'Central ideas, evidence, inferences', 'drill', 'rw', 'information_ideas', 'mixed', 'Practice finding main ideas, choosing the evidence that actually supports a claim, reading data, and completing inferences.', 11) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('4e32bc7d-ff90-570e-aefb-8ff6556a474b', '5552f280-f553-52d8-af83-acfa1effb6f7', 1, 'Reading: Information and Ideas', 'rw', 600) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f92fd26c-03a8-513c-a0fd-941c7abce5a9', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 1, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'Emperor penguins huddle in colonies of thousands during the Antarctic winter. Birds on the windward edge lose heat fastest, so the huddle continually rotates, moving outer birds inward in slow waves. No individual leads the movement; it emerges from each bird taking small steps toward warmth.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Emperor penguins choose leaders to organise their huddles."},{"key":"B","text":"Huddle rotation is an unplanned result of individual birds seeking warmth."},{"key":"C","text":"Penguins on the outside of a huddle rarely survive the winter."},{"key":"D","text":"Antarctic winters are colder than the penguins can tolerate."}]'::jsonb, 'B', null, 'The final sentence explicitly denies leadership and attributes the wave to individual steps toward warmth. Choice C invents a mortality claim the text never makes.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ca24e4e6-998d-5815-acaa-cbe3ca4bc5f4', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 2, 'information_ideas', 'evidence_textual', 'easy', 'mc', 'A student claims that the invention of cheap window glass changed domestic architecture more than any decorative fashion of the period did.', 'Which finding, if true, would most directly support the claim?', '[{"key":"A","text":"Glassmakers'' guilds grew rapidly during the period."},{"key":"B","text":"Room layouts across many house types shifted toward the exterior walls once glass prices fell."},{"key":"C","text":"Decorative plasterwork remained popular throughout the period."},{"key":"D","text":"Window taxes were introduced in several countries."}]'::jsonb, 'B', null, 'A change in how rooms are arranged, occurring across house types and tied to the price drop, is direct architectural consequence. Choice A shows the industry grew but says nothing about how buildings were designed.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('41362ae7-13df-530c-a80c-87e8504b79c1', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 3, 'information_ideas', 'inferences', 'medium', 'mc', 'Certain desert plants open their stomata only at night, taking in carbon dioxide and storing it as an acid until daylight. Photosynthesis then proceeds behind closed pores. Because water loss through stomata rises steeply with temperature, this timing suggests that for these plants _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"conserving water outweighs the cost of a more complex chemical pathway."},{"key":"B","text":"carbon dioxide is more abundant at night than during the day."},{"key":"C","text":"photosynthesis cannot occur while stomata are closed."},{"key":"D","text":"growth rates exceed those of plants in wetter habitats."}]'::jsonb, 'A', null, 'The plants accept an extra storage step in order to open their pores only when evaporation is lowest, which is a trade of complexity for water. Choice C contradicts the passage, which states photosynthesis proceeds with the pores shut.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('02780dd2-8f54-5e31-abf8-39d71e388d4f', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 4, 'information_ideas', 'evidence_quantitative', 'medium', 'mc', 'A library recorded loans of physical books before and after adding a self-service kiosk. Loans at the staffed desk fell from 4,200 to 2,600 per month, while kiosk loans reached 2,900. Total monthly loans went from 4,200 to 5,500.', 'Which choice best uses the data to evaluate the claim that the kiosk merely shifted existing loans rather than adding new ones?', '[{"key":"A","text":"Desk loans fell by 1,600, showing that borrowers moved to the kiosk."},{"key":"B","text":"Total loans rose by 1,300, more than can be explained by shifting alone."},{"key":"C","text":"Kiosk loans (2,900) exceeded remaining desk loans (2,600)."},{"key":"D","text":"Desk loans remained above 2,000 per month."}]'::jsonb, 'B', null, 'Pure substitution would leave the total unchanged, so the 1,300 increase in total loans is the figure that tests the claim. Choice A is consistent with both explanations and therefore cannot distinguish between them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('28dfd1d5-2e92-56f8-af1c-9f0538dd9585', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 5, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'Scholars once assumed the great earthworks of the Amazon were built after European contact, since early accounts described sparse populations. Radiocarbon dates now place many of them between 500 and 1200 CE, and the sparse populations of the accounts are increasingly read as the aftermath of introduced epidemics.', 'According to the text, why has the earlier assumption been revised?', '[{"key":"A","text":"New dating places the earthworks centuries before contact, and the sparse populations are reinterpreted."},{"key":"B","text":"The early accounts have been shown to be forgeries."},{"key":"C","text":"Archaeologists have found no earthworks older than 1200 CE."},{"key":"D","text":"Epidemics are now thought to have had little demographic effect."}]'::jsonb, 'A', null, 'Two things changed: the radiocarbon dates and the reading of the population reports as post-epidemic. Choice D reverses the passage, which relies on epidemics having had a large effect.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c70e938e-ed25-5edb-a0c1-8f18b494543b', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 6, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'In a study of 1,200 patients, a screening test identified 95 percent of those who had the condition. However, only 8 percent of people who tested positive actually had it, because the condition occurs in fewer than 1 in 500 people.', 'Which statement about the test is best supported by the text?', '[{"key":"A","text":"The test is inaccurate at detecting the condition when it is present."},{"key":"B","text":"A positive result is weak evidence of the condition because the condition is rare."},{"key":"C","text":"The test should be abandoned because 92 percent of its results are wrong."},{"key":"D","text":"Increasing the number of patients tested would improve the positive predictive value."}]'::jsonb, 'B', null, 'The test detects 95 percent of true cases, so its sensitivity is high; the low 8 percent figure follows from the small base rate producing many false positives. Choice C misstates the data, since the 92 percent applies only to positive results, not to all results.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8d094234-9749-5a85-a79d-244b2cb73ffd', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 7, 'information_ideas', 'inferences', 'hard', 'mc', 'Two neighbouring valleys share a climate and a soil type, but only one has terraced fields dating to the fifteenth century. Both have the same crop remains in the archaeological record, and both show the same population estimates for that century. The valley without terraces, however, has a gentler slope throughout. This suggests the terraces _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"were a response to steep terrain rather than to crop choice or population size."},{"key":"B","text":"supported crops that could not be grown on flat ground."},{"key":"C","text":"indicate a larger population than the estimates suggest."},{"key":"D","text":"were built long after the fifteenth century."}]'::jsonb, 'A', null, 'Climate, soil, crops and population are held constant across the two valleys, leaving slope as the only difference that can explain the terraces. Choice B is ruled out by the identical crop remains at both sites.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d9da6b54-7170-55fc-abab-165201d48b79', '4e32bc7d-ff90-570e-aefb-8ff6556a474b', 8, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'A researcher hypothesises that the poet composed the sequence for oral performance rather than for print.', 'Which finding, if true, would most directly support the hypothesis?', '[{"key":"A","text":"The poems were first printed in an expensive folio edition."},{"key":"B","text":"The poems use a repeating refrain and stress patterns that reset after every eight lines, features that aid memorisation."},{"key":"C","text":"The poet''s letters mention meeting with a printer."},{"key":"D","text":"The poems are shorter on average than the poet''s earlier work."}]'::jsonb, 'B', null, 'Mnemonic structure — refrains and regular resetting stress patterns — is evidence of design for voice and memory. Choice A points toward print production, and choice D is neutral because length alone implies nothing about medium.') on conflict (id) do nothing;
